records=json.loads(zlib.decompress(base64.b64decode("")))
UNIV=50063860; H=3066
human={
"SIG-589":"paridade por posição = assinatura 58 + soma 120–139 + 4 décadas ocupadas",
"DLT-321":"Δ2 + Δ5 ≥ 36 + Δ1 é o menor gap + pelo menos 3 gaps ≥ 12",
"ESP-503":"6 colunas diferentes + pelo menos 2 pares espelho decimal",
"ESP-682":"máximo 2 dezenas por classe módulo 5 + amplitude ≥55 + 2+ palíndromas",
"AFF-X-259":"score de afinidade de trincas/pares; candidato analítico de baixo ganho marginal"
}
def pois(k,lam):
    return sum(math.exp(-lam)*lam**i/math.factorial(i) for i in range(k+1))
def fi(n): return f"{int(n):,}".replace(",",".")
def fam_table(fam):
    rr=sorted([r for r in records if r["family"]==fam],key=lambda x:(x["marginal"],x["raw"]),reverse=True)
    out=[]
    for r in rr:
        freq=r["raw"]/UNIV; exp=H*freq; pv=pois(int(r["hist"]),exp); rid=r["id"]
        desc=human.get(rid,r["desc"]); wf=str(r["blocks"]).replace(","," / ")
        status="QUARENTENA" if rid in ["SIG-589","DLT-321","ESP-503"] else "REPROVADO"
        out.append(f'<tr><td><b>{html.escape(rid)}</b><br><span class="muted">{html.escape(desc)}</span></td><td>{int(r["hist"])}</td><td>{fi(r["raw"])}</td><td><b>{fi(r["marginal"])}</b></td><td>{100*freq:.5f}%</td><td>{exp:.2f}</td><td>{pv:.6f}</td><td>não / não</td><td>{html.escape(wf)}</td><td>3067 ✓</td><td><span class="level-badge level-{status.lower()}">{status}</span></td><td>não passou Bonferroni/FDR após 3.600 hipóteses</td></tr>')
    return "".join(out)
tables={f:fam_table(f) for f in ["DLT","ESP","SIG","AFF-X"]}

