fq="function exaQuarantineFlags(g){const rows=Array(6).fill(0);let top=0,H=0,V=0,D=0;for(const n of g){const r=Math.floor((n-1)/10),c=(n-1)%10;rows[r]++;top+=Number(r<3)}const sig=rows.filter(Boolean).sort((a,b)=>b-a).join('-');for(let i=0;i<g.length;i++)for(let j=i+1;j<g.length;j++){const ri=Math.floor((g[i]-1)/10),ci=(g[i]-1)%10,rj=Math.floor((g[j]-1)/10),cj=(g[j]-1)%10,dr=Math.abs(ri-rj),dc=Math.abs(ci-cj);if(dr===0&&dc===1)H++;else if(dr===1&&dc===0)V++;else if(dr===1&&dc===1)D++}return [top>=5&&sig==='3-3',g[0]>=20&&g[3]<=28,D>=4&&(H+V+D)>=5]}"
exa2="function exa2Flags(g){const d=g.slice(1).map((n,i)=>n-g[i]);let evmask=0;for(let i=0;i<6;i++)if(g[i]%2===0)evmask|=(1<<i);const occdec=new Set(g.map(n=>Math.floor((n-1)/10))).size,sum=g.reduce((a,b)=>a+b,0);const sig589=evmask===58&&sum>=120&&sum<=139&&occdec===4;const dlt321=d[1]+d[4]>=36&&d.indexOf(Math.min(...d))===0&&d.filter(x=>x>=12).length>=3;const cols=new Set(g.map(n=>(n-1)%10));let mirror=0,ss=new Set(g);for(const n of g){const r=Number(String(n).padStart(2,'0').split('').reverse().join(''));if(r>=1&&r<=60&&r!==n&&n<r&&ss.has(r))mirror++}const esp503=cols.size===6&&mirror>=2;return [sig589,dlt321,esp503]}"
