dyn=r"""function comboParts(a,k,start=0,p=[],out=[]){if(p.length===k){out.push(p.join('-'));return out}for(let i=start;i<=a.length-(k-p.length);i++)comboParts(a,k,i+1,[...p,a[i]],out);return out}
function affinityRows(k){const h=state.history,map=new Map;for(let ix=0;ix<h.length;ix++)for(const key of comboParts(h[ix].dezenas,k)){if(!map.has(key))map.set(key,[]);map.get(key).push(ix)}const expected=h.length*nCk(6,k)/nCk(60,k),rows=[];for(const [key,occ] of map){const obs=occ.length,lift=expected?obs/expected:0,last=occ.at(-1),gaps=occ.slice(1).map((x,i)=>x-occ[i]);const cur=h.length-1-last,avg=gaps.length?gaps.reduce((a,b)=>a+b,0)/gaps.length:0,max=gaps.length?Math.max(...gaps):0,w=n=>occ.filter(x=>x>=h.length-n).length;rows.push({key,obs,expected,lift,cur,avg,max,u50:w(50),u100:w(100),u500:w(500)})}return rows.sort((a,b)=>b.lift-a.lift||b.obs-a.obs).slice(0,10)}
function renderAffxAnalytics(){const el=$('#affx-analytics');if(!el)return;const mk=(title,rows)=>`<h3>${title}</h3><div class="table-wrap"><table><thead><tr><th>Grupo</th><th>Observado</th><th>Esperado</th><th>Lift</th><th>Atraso atual</th><th>Médio</th><th>Máximo</th><th>U50/U100/U500</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${r.key.split('-').map(x=>pad(+x)).join(' · ')}</b></td><td>${r.obs}</td><td>${r.expected.toFixed(2)}</td><td>${r.lift.toFixed(2)}×</td><td>${r.cur}</td><td>${r.avg.toFixed(1)}</td><td>${r.max}</td><td>${r.u50}/${r.u100}/${r.u500}</td></tr>`).join('')}</tbody></table></div>`;el.innerHTML=mk('Top 10 duplas por lift',affinityRows(2))+mk('Top 10 trincas por lift',affinityRows(3))}
function syncExa2Buttons(){$$('[data-exa2-toggle]').forEach(b=>{const id=b.dataset.exa2Toggle,on=!!state.rules.advanced[id]?.enabled;b.classList.toggle('on',on);b.textContent=on?'Desativar teste':'Ativar teste';b.setAttribute('aria-pressed',on?'true':'false')})}
function renderExaResearch(){renderAffxAnalytics();syncExa2Buttons();$$('[data-exa2-toggle]').forEach(b=>b.onclick=()=>{const id=b.dataset.exa2Toggle,a=state.rules.advanced[id];if(!a)return;state.rules.advanced[id]={...a,enabled:!a.enabled};persist();renderAdvanced();updateTop();syncExa2Buttons();tell((!a.enabled?'Ativado: ':'Desativado: ')+FILTER_DEFS.find(d=>d.id===id).label)})}
function deltaFeatures(g){const d=g.slice(1).map((n,i)=>n-g[i]),mn=Math.min(...d),mx=Math.max(...d);return{d,min:mn,max:mx,minPos:d.indexOf(mn)+1,maxPos:d.indexOf(mx)+1,sig:d.join('-')}}
function mirrorFeatures(g){const ss=new Set(g);let dec=0,comp=0;for(const n of g){const r=Number(String(n).padStart(2,'0').split('').reverse().join(''));if(r>=1&&r<=60&&r!==n&&n<r&&ss.has(r))dec++;const c=61-n;if(n<c&&ss.has(c))comp++}return{decimal:dec,comp61:comp,pal:g.filter(n=>[11,22,33,44,55].includes(n)).length}}
function renderDeltaResearch(){const manual=sorted([...state.fixed,...state.selected]),src=manual.length===6?manual:state.history.at(-1)?.dezenas;if(!src){$('#delta-analysis').innerHTML='<p class="empty-state">Sem jogo ou histórico.</p>';$('#mirror-analysis').innerHTML='';return}const f=deltaFeatures(src),h=state.history,dist=[0,1,2,3,4].map(i=>{const vals=h.map(x=>deltaFeatures(x.dezenas).d[i]),same=vals.filter(v=>v===f.d[i]).length;return{same,min:Math.min(...vals),max:Math.max(...vals),avg:vals.reduce((a,b)=>a+b,0)/vals.length}}),sigCount=h.filter(x=>deltaFeatures(x.dezenas).sig===f.sig).length;$('#delta-analysis').innerHTML=`<p><b>Jogo analisado:</b> ${src.map(pad).join(' · ')} ${manual.length===6?'<span class="tag">jogo manual</span>':'<span class="tag">último concurso</span>'}</p><div class="delta-grid">${f.d.map((v,i)=>`<div class="delta-box"><span>Δ${i+1}</span><strong>${v}</strong><small>${dist[i].same}/${h.length} no histórico · ${(100*dist[i].same/h.length).toFixed(2)}%</small></div>`).join('')}</div><div class="table-wrap" style="margin-top:14px"><table><tbody><tr><td>Assinatura completa</td><td><b>${f.sig}</b></td></tr><tr><td>Ocorrências exatas da assinatura</td><td>${sigCount} / ${h.length} (${(100*sigCount/h.length).toFixed(4)}%)</td></tr><tr><td>Menor gap / posição</td><td>${f.min} · Δ${f.minPos}</td></tr><tr><td>Maior gap / posição</td><td>${f.max} · Δ${f.maxPos}</td></tr></tbody></table></div><div class="table-wrap" style="margin-top:14px"><table><thead><tr><th>Delta</th><th>Valor atual</th><th>Média histórica</th><th>Menor</th><th>Maior</th><th>Frequência do valor</th></tr></thead><tbody>${dist.map((r,i)=>`<tr><td>Δ${i+1}</td><td>${f.d[i]}</td><td>${r.avg.toFixed(2)}</td><td>${r.min}</td><td>${r.max}</td><td>${r.same} (${(100*r.same/h.length).toFixed(2)}%)</td></tr>`).join('')}</tbody></table></div>`;const mf=mirrorFeatures(src),all=h.map(x=>mirrorFeatures(x.dezenas)),distM=k=>{const c={};for(const z of all)c[z[k]]=(c[z[k]]||0)+1;return Object.entries(c).sort((a,b)=>+a[0]-+b[0]).map(([n,v])=>`${n}: ${v}`).join(' · ')};$('#mirror-analysis').innerHTML=`<div class="mini-grid"><div class="mirror-card"><b>Espelho decimal</b><strong>${mf.decimal}</strong><p class="muted">12↔21, 04↔40. Histórico por quantidade: ${distM('decimal')}</p></div><div class="mirror-card"><b>Complementar soma 61</b><strong>${mf.comp61}</strong><p class="muted">01↔60, 02↔59. Histórico por quantidade: ${distM('comp61')}</p></div><div class="mirror-card"><b>Gêmeas / palíndromas</b><strong>${mf.pal}</strong><p class="muted">11,22,33,44,55. Histórico por quantidade: ${distM('pal')}</p></div></div>`}"""
